function flatBlack() {
  return new THREE.MeshBasicMaterial({
    color: 0x151515, transparent: true, opacity: 1,
    depthWrite: false, side: THREE.DoubleSide
  });
}

function bracePoints(w, dpt, n) {
  const V2 = THREE.Vector2;
  const segs = [
    new THREE.QuadraticBezierCurve(new V2(-w, 0), new V2(-w * 0.88, dpt * 0.62), new V2(-w * 0.45, dpt * 0.58)),
    new THREE.QuadraticBezierCurve(new V2(-w * 0.45, dpt * 0.58), new V2(-w * 0.13, dpt * 0.60), new V2(0, dpt)),
    new THREE.QuadraticBezierCurve(new V2(0, dpt), new V2(w * 0.13, dpt * 0.60), new V2(w * 0.45, dpt * 0.58)),
    new THREE.QuadraticBezierCurve(new V2(w * 0.45, dpt * 0.58), new V2(w * 0.88, dpt * 0.62), new V2(w, 0))
  ];
  const out = [];
  segs.forEach(c => c.getPoints(n).forEach(p => out.push(new THREE.Vector3(p.x, p.y, 0))));
  return out;
}

function stick(p1, p2, r, mat) {
  const dir = new THREE.Vector3().subVectors(p2, p1);
