/* ── labels ────────────────────────────────────────────────────────────── */
const _K = camera.position.distanceTo(controls.target) / 8;
const fs = px => (px * _K).toFixed(1) + 'px';

panels.forEach(P => {
  for (let i = 0; i < 3; i++) {
    P.fLab.push(addLabel('H', new THREE.Vector3(), { color: TXT_GREEN, bold: true, fontSize: fs(15) }));
    P.rLab.push(addLabel('H', new THREE.Vector3(), { color: TXT_MAG, bold: true, fontSize: fs(15) }));
    if (P.isRight) P.eLab.push(addLabel('4.0 kJ/mol', new THREE.Vector3(), { color: TXT_DARK, fontSize: fs(12.5) }));
  }
});

addLabel('Rotate rear<br>carbon 60&deg;', new THREE.Vector3(XARR, 0.68, 0), { color: '#111', fontSize: fs(12.5) });
addLabel('<b>Ethane&mdash;staggered<br>conformation</b>', new THREE.Vector3((XN_A + XM_A) / 2, -3.05, 0), { color: '#111', fontSize: fs(13.5) });
addLabel('<b>Ethane&mdash;eclipsed<br>conformation</b>', new THREE.Vector3((XN_B + XM_B) / 2, -3.05, 0), { color: '#111', fontSize: fs(13.5) });

/* ── state + update ────────────────────────────────────────────────────── */
let dihedral = 0;          // 0 = staggered, 60 = eclipsed
let target = 0;
let highlight = -1;

const elSlider = document.getElementById('dihedral');
const elDihVal = document.getElementById('dihVal');
const elTorVal = document.getElementById('torVal');
const elE = document.getElementById('eVal');
const elBar = document.getElementById('eBar');
const elHl = document.getElementById('hlInfo');

function setHighlight(i) {
  highlight = (highlight === i) ? -1 : i;
  elHl.innerHTML = highlight < 0
    ? 'Rotate to 60&deg;, then click one H&ndash;H pair (brace, letters or spheres) to isolate a single 4.0 kJ/mol interaction.'
