}
document.getElementById('btnClear').addEventListener('click', () => { highlight = -1; setHighlight(-1); highlight = -1; });

elSlider.addEventListener('input', () => { target = dihedral = parseFloat(elSlider.value); });

function labelAt(entry, group, x, y, z) {
  entry.pos.set(x, y, z || 0).applyMatrix4(group.matrixWorld);
}

function update() {
  const s = dihedral;
  const braceA = Math.max(0, Math.min(1, (s - 40) / 20));
  const lat = 0.28 * (s / 60);

  panels.forEach(P => {
    const sv = P.isRight ? s : 0;
    for (let i = 0; i < 3; i++) {
      const ra = (30 + 120 * i + sv) * DEG;
      P.rear[i].position.set(Math.cos(ra) * 1.31, Math.sin(ra) * 1.31, -0.02);
      P.rear[i].rotation.z = ra;

      const af = (90 + 120 * i) * DEG;
      const hlOn = P.isRight && highlight >= 0;
      const a = hlOn ? (i === highlight ? 1 : 0.32) : 1;

      P.front[i].material.opacity = a;
      P.rear[i].material.opacity = a;

      labelAt(P.fLab[i], P.group, Math.cos(af) * 1.84, Math.sin(af) * 1.84, 0.03);
      const px = Math.cos(ra - Math.PI / 2), py = Math.sin(ra - Math.PI / 2);
      labelAt(P.rLab[i], P.group, Math.cos(ra) * 1.84 + px * lat, Math.sin(ra) * 1.84 + py * lat, 0.03);

      const glow = (hlOn && i === highlight) ? '0 0 9px #ffcc00, 0 0 3px #ffcc00' : 'none';
      P.fLab[i].div.style.opacity = a; P.fLab[i].div.style.textShadow = glow;
      P.rLab[i].div.style.opacity = a; P.rLab[i].div.style.textShadow = glow;

      if (P.isRight) {
        P.braces[i].mat.opacity = braceA * a;
