        P.eLab[i].div.style.opacity = braceA * a;
        P.eLab[i].div.style.textShadow = glow === 'none' ? '0 1px 2px #fff' : glow;
        P.eLab[i].div.style.fontWeight = (hlOn && i === highlight) ? 'bold' : 'normal';
      }
    }
  });

  models.forEach(M => {
    M.rearG.rotation.z = (M.isRight ? s : 0) * DEG;
    for (let i = 0; i < 3; i++) {
      const hlOn = M.isRight && highlight >= 0;
      const on = hlOn && i === highlight;
      const a = hlOn ? (on ? 1 : 0.30) : 1;
      [M.frontH[i], M.rearH[i]].forEach(mesh => {
        mesh.material.opacity = a;
        mesh.material.emissive.setHex(on ? 0xffcc00 : 0x000000);
        mesh.material.emissiveIntensity = on ? 0.42 : 0;
      });
    }
  });

