  { t: 'Rotating the rear carbon', d: 30, n: 'Turning the rear carbon 30° swings the magenta hydrogens toward the green ones; in the model the red spheres slide toward the green spheres and torsional strain begins to build.' },
  { t: 'Eclipsed ethane', d: 60, n: 'At 60° each rear bond lies directly behind a front bond. The three braces mark three eclipsing H–H interactions, each worth 4.0 kJ/mol — 12 kJ/mol total. Click a pair to isolate one interaction.' }
];
let stepIdx = 0, playing = false, playTimer = null;

function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const st = STEPS[stepIdx];
  target = st.d;
  if (st.d < 60) { highlight = -1; setHighlight(-1); highlight = -1; }
  document.getElementById('stepTitle').textContent = (stepIdx + 1) + '. ' + st.t;
  document.getElementById('stepText').textContent = st.n;
}
document.getElementById('btnPrev').addEventListener('click', () => { stopPlay(); goToStep(stepIdx - 1); });
document.getElementById('btnNext').addEventListener('click', () => { stopPlay(); goToStep(stepIdx + 1); });
function stopPlay() { playing = false; clearInterval(playTimer); document.getElementById('btnPlay').textContent = '\u25B6 Play'; document.getElementById('btnPlay').classList.remove('active'); }
document.getElementById('btnPlay').addEventListener('click', () => {
  if (playing) { stopPlay(); return; }
  playing = true;
  document.getElementById('btnPlay').textContent = '\u23F8 Pause';
  document.getElementById('btnPlay').classList.add('active');
  goToStep(stepIdx + 1);
  playTimer = setInterval(() => goToStep(stepIdx + 1), 2600);
});
goToStep(0);
// @FIGURE_CODE_END

