function labelAt(entry, group, x, y, z) {
  entry.pos.set(x, y, z || 0).applyMatrix4(group.matrixWorld);
}

function update() {
  panels.forEach(P => {
    const sv = P.isRight ? 60 : dihedral;
    const lat = 0.30 * (sv / 60);
    for (let i = 0; i < 3; i++) {
      const ra = (30 + 120 * i + sv) * DEG;
      P.rear[i].position.set(Math.cos(ra) * 1.32, Math.sin(ra) * 1.32, -0.02);
      P.rear[i].rotation.z = ra;

      const af = (90 + 120 * i) * DEG;
      const hlOn = P.isRight && highlight >= 0;
      const on = hlOn && i === highlight;
      const a = hlOn ? (on ? 1 : 0.28) : 1;

      P.front[i].material.opacity = a;
      P.rear[i].material.opacity = a;

      labelAt(P.fLab[i], P.group, Math.cos(af) * 1.88, Math.sin(af) * 1.88, 0.03);
      const px = Math.cos(ra - Math.PI / 2), py = Math.sin(ra - Math.PI / 2);
      labelAt(P.rLab[i], P.group, Math.cos(ra) * 1.88 + px * lat, Math.sin(ra) * 1.88 + py * lat, 0.03);

      const glow = on ? '0 0 10px #ffcc00, 0 0 3px #ffcc00' : 'none';
      P.fLab[i].div.style.opacity = a; P.fLab[i].div.style.textShadow = glow;
      P.rLab[i].div.style.opacity = a; P.rLab[i].div.style.textShadow = glow;

      if (P.isRight) {
        P.braces[i].mat.opacity = a;
        labelAt(P.eLab[i], P.braces[i].group, 0, 0.56, 0);
        P.eLab[i].div.style.opacity = a;
        P.eLab[i].div.style.textShadow = on ? glow : '0 1px 2px #fff';
        P.eLab[i].div.style.fontWeight = on ? 'bold' : 'normal';
      }
    }
  });

  models.forEach(M => {
    M.rearG.rotation.z = (M.isRight ? 60 : dihedral) * DEG;
    for (let i = 0; i < 3; i++) {
      const hlOn = M.isRight && highlight >= 0;
      const on = hlOn && i === highlight;
      const a = hlOn ? (on ? 1 : 0.28) : 1;
      [M.frontH[i], M.rearH[i]].forEach(mesh => {
        mesh.material.opacity = a;
        mesh.material.emissive.setHex(on ? 0xffcc00 : 0x000000);
        mesh.material.emissiveIntensity = on ? 0.45 : 0;
      });
    }
  });

  const tor = 60 - dihedral;
  const E = 6 * (1 + Math.cos(3 * tor * DEG));
  elDihVal.textContent = Math.round(dihedral) + '\u00B0';
  elTorVal.textContent = Math.round(tor) + '\u00B0';
  elE.textContent = E.toFixed(1);
  elBar.style.width = (E / 12 * 100).toFixed(0) + '%';
  if (Math.abs(parseFloat(elSlider.value) - dihedral) > 0.5) elSlider.value = dihedral.toFixed(0);
}

