function stopPlay() {
  playing = false; clearInterval(playTimer);
  const b = document.getElementById('btnPlay');
  b.textContent = '\u25B6 Play'; b.classList.remove('active');
}
document.getElementById('btnPlay').addEventListener('click', () => {
  if (playing) { stopPlay(); return; }
  playing = true;
  const b = document.getElementById('btnPlay');
  b.textContent = '\u23F8 Pause'; b.classList.add('active');
  goToStep(stepIdx + 1);
  playTimer = setInterval(() => goToStep(stepIdx + 1), 2600);
});
goToStep(0);
setHighlight(-1);
// @FIGURE_CODE_END

