// @FIGURE_CODE_BEGIN
/* ── Element spec ────────────────────────────────────────────────────────
   Newman rear-carbon circle → RingGeometry(0.985,1.015) MeshBasic #151515 (billboarded)
   Newman front-carbon dot   → CircleGeometry(0.10)      MeshBasic #151515
   3 heavy front bonds       → PlaneGeometry(1.62,0.10)  MeshBasic #151515 (scale.y on highlight)
   3 thin rear bonds         → PlaneGeometry(0.64,0.055) MeshBasic #151515 (left pair rotates)
   front H letters (3)       → addLabel green  #1f9e57  bold 18px
   rear  H letters (3)       → addLabel magenta#E0218A  bold 18px
   carbons (2 per model)     → SphereGeometry(0.52) MeshPhysical #3f4247
   front hydrogens (3)       → SphereGeometry(0.37) MeshPhysical #3fbf55
   rear  hydrogens (3)       → SphereGeometry(0.34) MeshPhysical #9e2b1e
   sticks                    → CylinderGeometry(0.10/0.13) MeshPhysical #b8c2cc
   reaction arrow            → PlaneGeometry shaft + ConeGeometry head, black (billboarded)
   3 curly braces (right)    → TubeGeometry over quadratic Béziers; black base + red thick hi
   '4.0 kJ/mol' x3 / captions→ addLabel (white background, pushed out along brace normal)
   view                      → ORTHOGRAPHIC front-on: left model reads end-on (hexagon),
                               right model pre-tilted into the source's tripod pose
───────────────────────────────────────────────────────────────────────── */

const DEG = Math.PI / 180;
const TXT_GREEN = '#1f9e57', TXT_MAG = '#E0218A', TXT_DARK = '#1b1b1b', ACCENT = '#c81414';

/* lights */
scene.add(new THREE.AmbientLight(0xffffff, 0.62));
const _kLight = new THREE.DirectionalLight(0xffffff, 0.90); _kLight.position.set(2.5, 4.5, 8); scene.add(_kLight);
const _fLight = new THREE.DirectionalLight(0xffffff, 0.32); _fLight.position.set(-5, -2, 5); scene.add(_fLight);
const _rLight = new THREE.DirectionalLight(0xffffff, 0.20); _rLight.position.set(0, 3, -6); scene.add(_rLight);

const billboards = [];
const panels = [];
const models = [];

/* ── helpers ───────────────────────────────────────────────────────────── */
function flatBlack() {
  return new THREE.MeshBasicMaterial({
    color: 0x151515, transparent: true, opacity: 1,
    depthWrite: false, side: THREE.DoubleSide
  });
}

function bracePoints(w, dpt, n) {
  const V2 = THREE.Vector2;
  const segs = [
    new THREE.QuadraticBezierCurve(new V2(-w, 0), new V2(-w * 0.88, dpt * 0.62), new V2(-w * 0.45, dpt * 0.58)),
    new THREE.QuadraticBezierCurve(new V2(-w * 0.45, dpt * 0.58), new V2(-w * 0.13, dpt * 0.60), new V2(0, dpt)),
    new THREE.QuadraticBezierCurve(new V2(0, dpt), new V2(w * 0.13, dpt * 0.60), new V2(w * 0.45, dpt * 0.58)),
    new THREE.QuadraticBezierCurve(new V2(w * 0.45, dpt * 0.58), new V2(w * 0.88, dpt * 0.62), new V2(w, 0))
  ];
  const out = [];
  segs.forEach(c => c.getPoints(n).forEach(p => out.push(new THREE.Vector3(p.x, p.y, 0))));
  return out;
}

function braceTube(radius, color, op) {
  const pts = bracePoints(0.46, 0.22, 18);
  const curve = new THREE.CatmullRomCurve3(pts);
  const geo = new THREE.TubeGeometry(curve, 120, radius, 7, false);
  const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: op, depthWrite: false });
  const m = new THREE.Mesh(geo, mat);
  m.renderOrder = 15;
  return m;
}

function stick(p1, p2, r, mat) {
  const dir = new THREE.Vector3().subVectors(p2, p1);
  const len = dir.length();
  const m = new THREE.Mesh(new THREE.CylinderGeometry(r, r, len, 20), mat);
  m.position.copy(p1).addScaledVector(dir, 0.5);
  m.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
  return m;
}

/* ── Newman projection panel ───────────────────────────────────────────── */
const BRACE_R = 2.26;

function buildNewman(cx, isRight) {
  const g = new THREE.Group(); g.position.set(cx, 0, 0); scene.add(g); billboards.push(g);

  const circle = new THREE.Mesh(new THREE.RingGeometry(0.985, 1.015, 96), flatBlack());
  circle.renderOrder = 10; g.add(circle);

  const front = [], rear = [];
  for (let i = 0; i < 3; i++) {
    const a = (90 + 120 * i) * DEG;
    const fb = new THREE.Mesh(new THREE.PlaneGeometry(1.62, 0.10), flatBlack());
    fb.position.set(Math.cos(a) * 0.81, Math.sin(a) * 0.81, 0.02);
    fb.rotation.z = a; fb.renderOrder = 13; g.add(fb); front.push(fb);

    const rb = new THREE.Mesh(new THREE.PlaneGeometry(0.64, 0.055), flatBlack());
    rb.position.z = -0.02; rb.renderOrder = 11; g.add(rb); rear.push(rb);
  }

  const dot = new THREE.Mesh(new THREE.CircleGeometry(0.10, 32), flatBlack());
  dot.position.z = 0.03; dot.renderOrder = 14; g.add(dot);

  registerInteractive(circle, {
    title: 'Rear carbon', tooltip: 'Rear carbon (the circle)',
    body: 'In a Newman projection the circle IS the back carbon, seen end-on down the C–C bond. Its three bonds emerge from the circumference.'
  });
  registerInteractive(dot, {
    title: 'Front carbon', tooltip: 'Front carbon (the dot)',
    body: 'The dot at the centre is the front carbon. Its three bonds are drawn heavy and run all the way in to the centre point.'
  });

  const braces = [];
  if (isRight) {
    for (let i = 0; i < 3; i++) {
      const a = (90 + 120 * i) * DEG;
      const bg = new THREE.Group();
      bg.position.set(Math.cos(a) * BRACE_R, Math.sin(a) * BRACE_R, 0.04);
      bg.rotation.z = a - Math.PI / 2;
      const base = braceTube(0.022, 0x151515, 1);
      const hi = braceTube(0.055, 0xc81414, 1); hi.visible = false;
      bg.add(base); bg.add(hi); g.add(bg);
      braces.push({ group: bg, base, hi });

      const hit = new THREE.Mesh(
        new THREE.CircleGeometry(0.60, 24),
        new THREE.MeshBasicMaterial({ transparent: true, opacity: 0, depthWrite: false })
      );
      hit.position.set(Math.cos(a) * (BRACE_R - 0.22), Math.sin(a) * (BRACE_R - 0.22), 0.06);
      hit.renderOrder = 16; g.add(hit);
      registerInteractive(hit, {
        title: 'One eclipsing H–H interaction',
        tooltip: 'Click: isolate this 4.0 kJ/mol interaction',
        body: 'Each eclipsed hydrogen pair costs about 4.0 kJ/mol. Three such pairs give the full rotational barrier of ethane: 3 × 4.0 = 12 kJ/mol.',
        onClick: () => setHighlight(i)
      });
    }
  }

  const P = { group: g, front, rear, braces, isRight, fLab: [], rLab: [], eLab: [] };
  panels.push(P);
  return P;
}

/* ── ball-and-stick model ──────────────────────────────────────────────── */
function buildModel(cx, isRight) {
  const g = new THREE.Group();
  g.position.set(cx, 0, 0);
  // Left: essentially end-on down C–C → the six H form the alternating hexagon.
  // Right: the source's slightly off-axis tripod view.
  g.rotation.set(isRight ? 0.40 : 0.10, isRight ? -0.17 : -0.05, 0);
  scene.add(g);

  const half = 0.84;
  const cMat = () => new THREE.MeshPhysicalMaterial({ color: 0x3f4247, roughness: 0.30, metalness: 0.0, clearcoat: 0.75, clearcoatRoughness: 0.24, transparent: true });
  const sMat = new THREE.MeshPhysicalMaterial({ color: 0xb8c2cc, roughness: 0.45, metalness: 0.0, transparent: true });

  const rearG = new THREE.Group(); g.add(rearG);

  const c2 = new THREE.Mesh(new THREE.SphereGeometry(0.50, 48, 32), cMat());
  c2.position.z = -half; rearG.add(c2);
  const c1 = new THREE.Mesh(new THREE.SphereGeometry(0.53, 48, 32), cMat());
  c1.position.z = half; g.add(c1);
  g.add(stick(new THREE.Vector3(0, 0, -half), new THREE.Vector3(0, 0, half), 0.13, sMat));

  const bond = 1.22;
  const rad = Math.sin(109.5 * DEG) * bond;
  const axl = -Math.cos(109.5 * DEG) * bond;
  const frontH = [], rearH = [];

  for (let i = 0; i < 3; i++) {
    const af = (90 + 120 * i) * DEG;
    const hp = new THREE.Vector3(Math.cos(af) * rad, Math.sin(af) * rad, half + axl);
    const h = new THREE.Mesh(new THREE.SphereGeometry(0.37, 40, 28),
      new THREE.MeshPhysicalMaterial({ color: 0x3fbf55, roughness: 0.28, clearcoat: 0.8, clearcoatRoughness: 0.2, transparent: true }));
    h.position.copy(hp); g.add(h); frontH.push(h);
    g.add(stick(new THREE.Vector3(0, 0, half), hp, 0.10, sMat));

    const ar = (30 + 120 * i) * DEG;
    const rp = new THREE.Vector3(Math.cos(ar) * rad, Math.sin(ar) * rad, -half - axl);
    const rh = new THREE.Mesh(new THREE.SphereGeometry(0.34, 40, 28),
      new THREE.MeshPhysicalMaterial({ color: 0x9e2b1e, roughness: 0.30, clearcoat: 0.7, clearcoatRoughness: 0.25, transparent: true }));
    rh.position.copy(rp); rearG.add(rh); rearH.push(rh);
    rearG.add(stick(new THREE.Vector3(0, 0, -half), rp, 0.10, sMat));

    if (isRight) {
      const info = {
        title: 'One eclipsing H–H interaction',
        tooltip: 'Click: isolate this 4.0 kJ/mol interaction',
        body: 'When this green (front) and red (rear) hydrogen line up, their bonding electron clouds repel: about 4.0 kJ/mol of torsional strain. Three pairs → 12 kJ/mol.',
        onClick: () => setHighlight(i)
      };
      registerInteractive(h, info);
      registerInteractive(rh, info);
    } else {
      const info = {
        title: 'Staggered hydrogens',
        tooltip: 'Staggered: 60° apart',
        body: 'Seen end-on down the C–C bond, the green (front) and red (rear) hydrogens alternate in a hexagon — each pair 60° apart, so repulsion is minimal.'
      };
      registerInteractive(h, info);
      registerInteractive(rh, info);
    }
  }

  const M = { group: g, rearG, frontH, rearH, isRight };
  models.push(M);
  return M;
}

/* ── layout ────────────────────────────────────────────────────────────── */
const XN_A = -7.6, XM_A = -4.05, XARR = -1.15, XN_B = 2.2, XM_B = 6.3;
const panelL = buildNewman(XN_A, false);
const modelL = buildModel(XM_A, false);
const panelR = buildNewman(XN_B, true);
const modelR = buildModel(XM_B, true);

/* reaction arrow */
const arrowG = new THREE.Group(); arrowG.position.set(XARR, 0, 0); scene.add(arrowG); billboards.push(arrowG);
{
  const m = flatBlack();
  const shaft = new THREE.Mesh(new THREE.PlaneGeometry(1.72, 0.05), m);
  shaft.position.x = -0.16; shaft.renderOrder = 12; arrowG.add(shaft);
  const head = new THREE.Mesh(new THREE.ConeGeometry(0.125, 0.34, 28), m);
  head.rotation.z = -Math.PI / 2; head.position.x = 0.87; head.renderOrder = 12; arrowG.add(head);
}

/* tight invisible padding so the auto-fit only reserves room for HTML text */
{
  const padMat = new THREE.MeshBasicMaterial({ transparent: true, opacity: 0, depthWrite: false });
  [[-9.85, 3.15], [8.05, 3.15], [-9.85, -3.45], [8.05, -3.45]].forEach(([x, y]) => {
    const p = new THREE.Mesh(new THREE.PlaneGeometry(0.02, 0.02), padMat);
    p.position.set(x, y, 0); scene.add(p);
  });
}

/* ── camera (after all geometry) ───────────────────────────────────────── */
setCameraView({ projection: 'orthographic', azimuthDeg: 90, elevationDeg: 0, rollDeg: 0, heightFraction: 0.99 });
document.getElementById('btnReset').style.display = '';

/* ── labels ────────────────────────────────────────────────────────────── */
const FS_H = '18px', FS_KJ = '14.5px', FS_CAP = '16px', FS_ROT = '14.5px';
const LBL_BG = 'rgba(255,255,255,0.92)';

panels.forEach(P => {
  for (let i = 0; i < 3; i++) {
    P.fLab.push(addLabel('H', new THREE.Vector3(), { color: TXT_GREEN, bold: true, fontSize: FS_H }));
    P.rLab.push(addLabel('H', new THREE.Vector3(), { color: TXT_MAG, bold: true, fontSize: FS_H }));
    if (P.isRight) {
      const off = i === 0 ? [0, -4] : (i === 1 ? [-10, 10] : [10, 10]);
      P.eLab.push(addLabel('4.0 kJ/mol', new THREE.Vector3(),
        { color: TXT_DARK, fontSize: FS_KJ, offset: off, background: LBL_BG }));
    }
  }
});

addLabel('Rotate rear<br>carbon 60&deg;', new THREE.Vector3(XARR, 0.62, 0), { color: '#111', fontSize: FS_ROT });
addLabel('<b>Ethane&mdash;staggered<br>conformation</b>', new THREE.Vector3((XN_A + XM_A) / 2, -3.00, 0), { color: '#111', fontSize: FS_CAP });
addLabel('<b>Ethane&mdash;eclipsed<br>conformation</b>', new THREE.Vector3((XN_B + XM_B) / 2, -3.00, 0), { color: '#111', fontSize: FS_CAP });

/* ── state + update ────────────────────────────────────────────────────── */
let dihedral = 0;          // left molecule: 0 = staggered, 60 = eclipsed
let target = 0;
let highlight = -1;

const elSlider = document.getElementById('dihedral');
const elDihVal = document.getElementById('dihVal');
const elTorVal = document.getElementById('torVal');
const elE = document.getElementById('eVal');
const elBar = document.getElementById('eBar');
const elHl = document.getElementById('hlInfo');

function setHighlight(i) {
  highlight = (i < 0) ? -1 : (highlight === i ? -1 : i);
  elHl.innerHTML = highlight < 0
    ? 'Click one H&ndash;H pair on the right &mdash; a brace, the H letters or the spheres &mdash; to isolate a single 4.0 kJ/mol interaction.'
    : 'Isolated pair <b>' + (highlight + 1) + ' of 3</b>: the red brace marks one eclipsing H&ndash;H interaction = <b>4.0 kJ/mol</b>. All three together give the 12 kJ/mol rotational barrier.';
  for (let k = 0; k < 3; k++) {
    const b = document.getElementById('btnHl' + k);
    if (b) b.classList.toggle('active', highlight === k);
  }
}
document.getElementById('btnClear').addEventListener('click', () => setHighlight(-1));
[0, 1, 2].forEach(k => document.getElementById('btnHl' + k)
  .addEventListener('click', () => setHighlight(highlight === k ? -1 : k)));

elSlider.addEventListener('input', () => { target = dihedral = parseFloat(elSlider.value); });

function labelAt(entry, group, x, y, z) {
  entry.pos.set(x, y, z || 0).applyMatrix4(group.matrixWorld);
}

function update() {
  panels.forEach(P => {
    const sv = P.isRight ? 60 : dihedral;
    const lat = 0.30 * (sv / 60);
    for (let i = 0; i < 3; i++) {
      const ra = (30 + 120 * i + sv) * DEG;
      P.rear[i].position.set(Math.cos(ra) * 1.32, Math.sin(ra) * 1.32, -0.02);
      P.rear[i].rotation.z = ra;

      const af = (90 + 120 * i) * DEG;
      const hlOn = P.isRight && highlight >= 0;
      const on = hlOn && i === highlight;
      const a = hlOn ? (on ? 1 : 0.18) : 1;

      P.front[i].material.opacity = a;
      P.rear[i].material.opacity = a;
      P.front[i].scale.y = on ? 2.1 : 1;
      P.rear[i].scale.y = on ? 2.3 : 1;

      labelAt(P.fLab[i], P.group, Math.cos(af) * 1.88, Math.sin(af) * 1.88, 0.03);
      const px = Math.cos(ra - Math.PI / 2), py = Math.sin(ra - Math.PI / 2);
      labelAt(P.rLab[i], P.group, Math.cos(ra) * 1.88 + px * lat, Math.sin(ra) * 1.88 + py * lat, 0.03);

      const glow = on ? '0 0 10px #ffd34d, 0 0 3px #ffd34d' : 'none';
      P.fLab[i].div.style.opacity = a; P.fLab[i].div.style.textShadow = glow;
      P.rLab[i].div.style.opacity = a; P.rLab[i].div.style.textShadow = glow;

      if (P.isRight) {
        const B = P.braces[i];
        B.base.visible = !on;
        B.hi.visible = on;
        B.base.material.opacity = a;
        const dist = (i === 0) ? 0.60 : 0.96;
        labelAt(P.eLab[i], B.group, 0, dist, 0);
        const dv = P.eLab[i].div;
        dv.style.opacity = a;
        dv.style.color = on ? ACCENT : TXT_DARK;
        dv.style.fontWeight = on ? 'bold' : 'normal';
      }
    }
  });

  models.forEach(M => {
    M.rearG.rotation.z = (M.isRight ? 60 : dihedral) * DEG;
    for (let i = 0; i < 3; i++) {
      const hlOn = M.isRight && highlight >= 0;
      const on = hlOn && i === highlight;
      const a = hlOn ? (on ? 1 : 0.20) : 1;
      [M.frontH[i], M.rearH[i]].forEach(mesh => {
        mesh.material.opacity = a;
        mesh.material.emissive.setHex(on ? 0xffcc00 : 0x000000);
        mesh.material.emissiveIntensity = on ? 0.45 : 0;
      });
    }
  });

  const tor = 60 - dihedral;
  const E = 6 * (1 + Math.cos(3 * tor * DEG));
  elDihVal.textContent = Math.round(dihedral) + '\u00B0';
  elTorVal.textContent = Math.round(tor) + '\u00B0';
  elE.textContent = E.toFixed(1);
  elBar.style.width = (E / 12 * 100).toFixed(0) + '%';
  if (Math.abs(parseFloat(elSlider.value) - dihedral) > 0.5) elSlider.value = dihedral.toFixed(0);
}

/* ── own animation loop (billboards + tween) ───────────────────────────── */
function figLoop() {
  requestAnimationFrame(figLoop);
  for (const g of billboards) { g.quaternion.copy(camera.quaternion); g.updateMatrixWorld(true); }
  if (Math.abs(dihedral - target) > 0.08) dihedral += (target - dihedral) * 0.10;
  else dihedral = target;
  update();
}
figLoop();

/* ── demo steps ────────────────────────────────────────────────────────── */
const STEPS = [
  { t: 'Staggered ethane (left)', d: 0, n: 'Front bonds point up, down-left and down-right; rear bonds bisect them at left, right and bottom. Seen end-on, the green (front) and red (rear) hydrogens of the model alternate in a hexagon — 60° apart — the lowest-energy conformation.' },
  { t: 'Rotating the rear carbon', d: 30, n: 'Turning the left rear carbon 30° swings the magenta hydrogens toward the green ones; the red spheres slide toward the green spheres and torsional strain starts to build.' },
  { t: 'Eclipsed ethane (matches the right)', d: 60, n: 'After a full 60° rotation each rear bond lies directly behind a front bond — the left molecule now matches the eclipsed reference on the right. The three braces mark three eclipsing H–H interactions, 4.0 kJ/mol each, 12 kJ/mol total.' }
];
let stepIdx = 0, playing = false, playTimer = null;

function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const st = STEPS[stepIdx];
  target = st.d;
  document.getElementById('stepTitle').textContent = (stepIdx + 1) + '. ' + st.t;
  document.getElementById('stepText').textContent = st.n;
}
document.getElementById('btnPrev').addEventListener('click', () => { stopPlay(); goToStep(stepIdx - 1); });
document.getElementById('btnNext').addEventListener('click', () => { stopPlay(); goToStep(stepIdx + 1); });
function stopPlay() {
  playing = false; clearInterval(playTimer);
  const b = document.getElementById('btnPlay');
  b.textContent = '\u25B6 Play'; b.classList.remove('active');
}
document.getElementById('btnPlay').addEventListener('click', () => {
  if (playing) { stopPlay(); return; }
  playing = true;
  const b = document.getElementById('btnPlay');
  b.textContent = '\u23F8 Pause'; b.classList.add('active');
  goToStep(stepIdx + 1);
  playTimer = setInterval(() => goToStep(stepIdx + 1), 2600);
});
goToStep(0);
setHighlight(-1);
// @FIGURE_CODE_END

Output ONLY the JSON evaluation object.
